# Let me carefully trace each transformation
inputs = ['iyhb', 'ac', 'cehfdw', 'ay', 'vbbvf']
outputs = ['iubwhb', 'ac', 'cuhfkvw', 'aubw', 'vbbvf']

print("Input -> Output analysis:")
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    print(f"{i+1}. '{inp}' -> '{outp}'")

print("\nDetailed character analysis:")
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    print(f"Example {i+1}: '{inp}' -> '{outp}'")
    if inp != outp:
        # Find differences
        min_len = min(len(inp), len(outp))
        for j in range(min_len):
            if inp[j] != outp[j]:
                print(f"  Position {j}: '{inp[j]}' -> '{outp[j]}'")
        if len(inp) != len(outp):
            if len(inp) > len(outp):
                print(f"  Extra chars removed at end: '{inp[len(outp):]}'")
            else:
                print(f"  Extra chars added at end: '{outp[len(inp):]}'")
    else:
        print("  No changes")
    print()

